export const TABLET_ENTER_DURATION=866,TABLET_CONFIRM_DURATION=500,PHONE_ENTER_DURATION=517,PHONE_CONFIRM_DURATION=333,ABORT_DURATION=500,TABLET_APP_PAIR_LAUNCH_DURATION=998,PHONE_APP_PAIR_LAUNCH_DURATION=915,DESKTOP_FADE_OUT_DURATION=200,SPLIT_LAUNCH_DURATION=370,SPLIT_DIVIDER_ANIM_DURATION=100,TABLET_BREAKPOINT=768;export function isTabletWidth(e){return Number.isFinite(e)&&e>=768}export function splitTimingsFor(e){const t=isTabletWidth(e);return{device:t?"tablet":"phone",enter:t?866:517,confirm:t?500:333,appPair:t?998:915,abort:500,desktopFade:200,launch:370,divider:100}}export const APP_PAIR_STAGES=Object.freeze({stagedRectSlide:Object.freeze({start:0,end:.55}),iconFade:Object.freeze({start:.1,end:.4}),appReveal:Object.freeze({start:.3,end:1}),cellSplit:Object.freeze({start:0,end:1})}),PANE_B_ARM_AT=.25,PANE_A_SLIDE_SPAN=.55,PANE_B_SLIDE_SPAN=.3;export function stageProgress(e,t){if(!Number.isFinite(e))return 0;const _=t.end-t.start;return _<=0?e>=t.end?1:0:Math.min(1,Math.max(0,(e-t.start)/_))}export function appPairStageProgress(e){return{stagedRectSlide:stageProgress(e,APP_PAIR_STAGES.stagedRectSlide),iconFade:stageProgress(e,APP_PAIR_STAGES.iconFade),appReveal:stageProgress(e,APP_PAIR_STAGES.appReveal),cellSplit:stageProgress(e,APP_PAIR_STAGES.cellSplit)}}
